//! Emoji (FluxGram part 4): Unicode's emoji by category, in the order of the standard's list
//! (`emoji-test.txt`, Emoji 15.1, the fully-qualified ones), with their names and keywords in
//! English and Russian (CLDR's annotations) for the search, and skin tones for those that take
//! them. The table ([`data`]) is generated by `scripts/gen-emoji.py` (the sources' versions are
//! pinned there and named at the table's top), not read at run time. The field's panel
//! ([`crate::plugin_conversation`]) shows them; any chat of a plugin may.
//!
//! The search goes by words: each word of the query starts a word of the emoji's names or keywords,
//! in either language ("ё" as "е"); those whose names match come first, each group in the table's
//! order. Skin tones are one choice for all ([`Tone`]): an emoji that takes them shows in it.
//!
//! What the user chose lately and their tone are kept in a small file of their own ([`Recent`]):
//! `emoji-recent.json` next to Flux's other state (`FLUX_EMOJI_RECENT_FILE` — another file; in a
//! scenario without it, nothing is read or written).

mod data;

use std::collections::HashMap;
use std::ffi::OsString;
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::OnceLock;

use gpui::{App, Global};
use serde_json::{Value, json};

use crate::i18n::{self, Lang};

/// An emoji of the table.
#[derive(Debug)]
pub struct Emoji {
    /// The emoji itself, fully qualified.
    pub text: &'static str,
    /// CLDR's English and Russian names: "thumbs up", "большой палец вверх".
    pub name: &'static str,
    pub name_ru: &'static str,
    /// The search's words: lowercased, "ё" as "е", the names' first.
    words: &'static str,
    /// How many of `words` are the names'.
    name_words: u8,
    /// Its five skin tones' variants in [`data::TONES`]; none — it takes none.
    tones: Option<u16>,
}

/// A category of the panel: its emoji in the table's order.
#[derive(Debug)]
pub struct Category {
    /// In English, for `tr`: "Smileys & People".
    pub title: &'static str,
    /// The emoji standing for it in the panel's strip.
    pub icon: &'static str,
    start: usize,
    end: usize,
}

impl Category {
    pub fn emoji(&self) -> &'static [Emoji] {
        &data::EMOJI[self.start..self.end]
    }
}

/// A skin tone: none (the yellow of the emoji), then light → dark (Fitzpatrick 1–2 … 6).
pub type Tone = u8;
/// The tones to choose from, none first.
pub const TONES: Tone = 6;

/// The circles of the tone choice: the emoji's yellow, then the five tones' swatches (content's
/// colors, as an avatar's — not the theme's).
const TONE_SWATCHES: [u32; TONES as usize] =
    [0xFFC83D, 0xF7DECE, 0xF3D2A2, 0xD5AB88, 0xAF7E57, 0x7C533E];

/// A tone's circle.
pub fn tone_swatch(tone: Tone) -> gpui::Hsla {
    gpui::rgb(TONE_SWATCHES[usize::from(tone.min(TONES - 1))]).into()
}

impl Emoji {
    /// The name in the interface's language.
    pub fn local_name(&self) -> &'static str {
        match i18n::lang() {
            Lang::Ru if !self.name_ru.is_empty() => self.name_ru,
            _ => self.name,
        }
    }

    fn words(&self) -> impl Iterator<Item = (usize, &'static str)> {
        self.words.split(' ').enumerate()
    }
}

/// The categories in order.
pub fn categories() -> &'static [Category] {
    data::CATEGORIES
}

/// The emoji in `tone` (0 — none); one that takes no tones as it is.
pub fn with_tone(emoji: &Emoji, tone: Tone) -> &'static str {
    match (emoji.tones, tone) {
        (Some(index), 1..=5) => data::TONES[usize::from(index)][usize::from(tone - 1)],
        _ => emoji.text,
    }
}

/// The emoji of the table a text is, in any of its tones.
pub fn find(text: &str) -> Option<&'static Emoji> {
    static INDEX: OnceLock<HashMap<&'static str, usize>> = OnceLock::new();
    let index = INDEX.get_or_init(|| {
        let mut index = HashMap::new();
        for (at, emoji) in data::EMOJI.iter().enumerate() {
            index.insert(emoji.text, at);
            if let Some(tones) = emoji.tones {
                for variant in data::TONES[usize::from(tones)] {
                    index.insert(variant, at);
                }
            }
        }
        index
    });
    index.get(text).map(|&at| &data::EMOJI[at])
}

/// A query's words as the table keeps its own: lowercased, "ё" as "е".
fn query_words(query: &str) -> Vec<String> {
    query
        .to_lowercase()
        .replace('ё', "е")
        .split(|c: char| c.is_whitespace() || c == ',' || c == ':')
        .filter(|word| !word.is_empty())
        .map(str::to_string)
        .collect()
}

/// The emoji whose names or keywords (Russian and English) have words starting with each word of
/// the query: the names' matches first, then the keywords', each in the table's order. An empty
/// query finds nothing.
pub fn search(query: &str) -> Vec<&'static Emoji> {
    let words = query_words(query);
    if words.is_empty() {
        return Vec::new();
    }
    let mut named = Vec::new();
    let mut other = Vec::new();
    for emoji in data::EMOJI {
        let mut in_name = true;
        let found = words.iter().all(|word| {
            let mut hit = None;
            for (at, candidate) in emoji.words() {
                if candidate.starts_with(word.as_str()) {
                    let name = at < usize::from(emoji.name_words);
                    hit = Some(hit.unwrap_or(false) || name);
                    if name {
                        break;
                    }
                }
            }
            if hit == Some(false) {
                in_name = false;
            }
            hit.is_some()
        });
        if found {
            if in_name {
                named.push(emoji);
            } else {
                other.push(emoji);
            }
        }
    }
    named.extend(other);
    named
}

// --- What the user chose lately ---

/// The panel's recent emoji, at most this many.
pub const MAX_RECENT: usize = 27;

/// The emoji chosen lately (the latest first, each in no tone: they show in the current one) and
/// the skin tone chosen — shared by every panel, kept in their file.
#[derive(Default)]
pub struct Recent {
    pub emoji: Vec<&'static Emoji>,
    pub tone: Tone,
    path: Option<PathBuf>,
}

impl Global for Recent {}

impl Recent {
    /// The memory, read from its file the first time it is asked for.
    pub fn get(cx: &mut App) -> &Recent {
        Self::load_once(cx);
        cx.global::<Recent>()
    }

    fn load_once(cx: &mut App) {
        if cx.has_global::<Recent>() {
            return;
        }
        let path = store_path_for(
            std::env::var_os("FLUX_EMOJI_RECENT_FILE"),
            std::env::var_os("FLUX_SCENARIO").is_some(),
            flux_platform::paths::home().map(OsString::from),
        );
        let mut recent = path
            .as_deref()
            .and_then(|path| fs::read_to_string(path).ok())
            .map(|text| parse(&text))
            .unwrap_or_default();
        recent.path = path;
        cx.set_global(recent);
    }

    /// An emoji was chosen: first among the recent ones, saved.
    pub fn chose(emoji: &'static Emoji, cx: &mut App) {
        Self::load_once(cx);
        let recent = cx.global_mut::<Recent>();
        recent.emoji.retain(|other| other.text != emoji.text);
        recent.emoji.insert(0, emoji);
        recent.emoji.truncate(MAX_RECENT);
        recent.save();
    }

    /// The skin tone was chosen: saved.
    pub fn set_tone(tone: Tone, cx: &mut App) {
        Self::load_once(cx);
        let recent = cx.global_mut::<Recent>();
        recent.tone = tone.min(TONES - 1);
        recent.save();
    }

    fn save(&self) {
        let Some(path) = &self.path else {
            return;
        };
        let text = json!({
            "recent": self.emoji.iter().map(|emoji| emoji.text).collect::<Vec<_>>(),
            "tone": self.tone,
        });
        if let Err(error) = write(path, &format!("{text:#}\n")) {
            eprintln!("flux: can't save {}: {error}", path.display());
        }
    }
}

/// Where the memory is kept: an explicit file, otherwise (outside a scenario) next to Flux's
/// other state.
fn store_path_for(
    file: Option<OsString>,
    scenario: bool,
    home: Option<OsString>,
) -> Option<PathBuf> {
    if let Some(file) = file.filter(|file| !file.is_empty()) {
        return Some(file.into());
    }
    if scenario {
        return None;
    }
    let home = PathBuf::from(home?);
    Some(flux_platform::paths::support_dir_in(&home).join("emoji-recent.json"))
}

/// File → memory: emoji the table doesn't know are skipped, a broken file is an empty memory.
fn parse(text: &str) -> Recent {
    let Ok(value) = serde_json::from_str::<Value>(text) else {
        return Recent::default();
    };
    let mut emoji: Vec<&'static Emoji> = Vec::new();
    for text in value["recent"].as_array().into_iter().flatten() {
        if let Some(found) = text.as_str().and_then(find)
            && !emoji.iter().any(|other| other.text == found.text)
        {
            emoji.push(found);
        }
    }
    emoji.truncate(MAX_RECENT);
    let tone = value["tone"]
        .as_u64()
        .and_then(|tone| Tone::try_from(tone).ok())
        .filter(|tone| *tone < TONES)
        .unwrap_or(0);
    Recent {
        emoji,
        tone,
        path: None,
    }
}

fn write(path: &Path, text: &str) -> std::io::Result<()> {
    if let Some(dir) = path.parent() {
        fs::create_dir_all(dir)?;
    }
    let temp = path.with_extension("json.flux-tmp");
    fs::write(&temp, text)?;
    fs::rename(&temp, path).inspect_err(|_| {
        fs::remove_file(&temp).ok();
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn texts(found: &[&Emoji]) -> Vec<&'static str> {
        found.iter().map(|emoji| emoji.text).collect()
    }

    #[test]
    fn the_categories_cover_the_table_in_order() {
        let categories = categories();
        assert_eq!(categories.len(), 8);
        assert_eq!(categories[0].title, "Smileys & People");
        assert_eq!(categories[7].title, "Flags");
        assert_eq!(categories[0].emoji()[0].text, "😀");
        for pair in categories.windows(2) {
            assert_eq!(pair[0].end, pair[1].start);
        }
        assert_eq!(categories[7].end, data::EMOJI.len());
        // Fully qualified, no bare tones and no toned variants among them.
        assert!(data::EMOJI.iter().any(|emoji| emoji.text == "❤️"));
        assert!(!data::EMOJI.iter().any(|emoji| emoji.text == "❤"));
        assert!(!data::EMOJI.iter().any(|emoji| emoji.text == "🏻"));
        assert!(!data::EMOJI.iter().any(|emoji| emoji.text == "👍🏽"));
        assert!(categories[7].emoji().iter().any(|emoji| emoji.text == "🇷🇺"));
    }

    #[test]
    fn the_search_goes_by_russian_and_english_words() {
        let cats = texts(&search("кот"));
        assert!(cats.contains(&"🐱"), "{cats:?}");
        assert!(cats.contains(&"🐈"), "{cats:?}");
        let cats = texts(&search("cat"));
        assert!(cats.contains(&"🐱") && cats.contains(&"😺"), "{cats:?}");
        // A name's match before a keyword's: "cat face" before what is only tagged "cat".
        let face = cats.iter().position(|text| *text == "🐱").unwrap();
        let tagged = cats.iter().position(|text| *text == "🐅");
        assert!(tagged.is_none_or(|tagged| face < tagged), "{cats:?}");
        let hearts = texts(&search("сердце"));
        assert!(hearts.contains(&"❤️"), "{hearts:?}");
        let thumbs = texts(&search("thumbs"));
        assert_eq!(&thumbs[..2], ["👍", "👎"]);
        // Every word of the query, each a word's start; "ё" as "е"; case doesn't matter.
        assert_eq!(texts(&search("Thumbs Do")), ["👎"]);
        assert!(texts(&search("ёлка")).contains(&"🎄"));
        assert!(texts(&search("россия")).contains(&"🇷🇺"));
        assert!(search("  ").is_empty());
        assert!(search("qqqzzz").is_empty());
    }

    #[test]
    fn tones_go_to_those_that_take_them() {
        let thumbs = find("👍").unwrap();
        assert!(thumbs.tones.is_some());
        assert_eq!(with_tone(thumbs, 0), "👍");
        assert_eq!(with_tone(thumbs, 1), "👍🏻");
        assert_eq!(with_tone(thumbs, 5), "👍🏿");
        let cat = find("🐱").unwrap();
        assert!(cat.tones.is_none());
        assert_eq!(with_tone(cat, 3), "🐱");
        // A toned variant is found as its emoji.
        assert_eq!(find("👍🏽").unwrap().text, "👍");
        // People alike in a couple take the tone together.
        let hands = find("🧑‍🤝‍🧑").unwrap();
        assert_eq!(with_tone(hands, 2), "🧑🏼‍🤝‍🧑🏼");
    }

    #[test]
    fn the_memory_reads_what_it_knows() {
        let recent = parse(r#"{"recent": ["👍", "nope", "🐱", "👍🏽"], "tone": 3}"#);
        assert_eq!(texts(&recent.emoji), ["👍", "🐱"]);
        assert_eq!(recent.tone, 3);
        let broken = parse("{");
        assert!(broken.emoji.is_empty() && broken.tone == 0);
        assert_eq!(parse(r#"{"tone": 9}"#).tone, 0);
    }

    #[test]
    fn the_memory_lives_next_to_the_other_state() {
        let file = store_path_for(Some("/tmp/x.json".into()), true, None);
        assert_eq!(file, Some(PathBuf::from("/tmp/x.json")));
        assert_eq!(store_path_for(None, true, Some("/home/a".into())), None);
        let path = store_path_for(None, false, Some("/home/a".into())).unwrap();
        assert!(path.ends_with("emoji-recent.json"));
    }
}
